    node->val = val;
    node->left = NULL;
    node->right = NULL;
    return node;
}

TreeNode* build_tree_helper(int *preorder, int pre_start, int pre_end,
                            int *inorder, int in_start, int in_end) {
    if (pre_start > pre_end || in_start > in_end) return NULL;

    int root_val = preorder[pre_start];
    TreeNode *root = create_node(root_val);

    int in_root_idx = in_start;
    while (in_root_idx <= in_end && inorder[in_root_idx] != root_val) {
        in_root_idx++;
